import "./editorial-work-index.css";

export interface WorkIndexItem {
  title: string;
  discipline: string;
  href: string;
}

export interface EditorialWorkIndexProps {
  title: string;
  projects: WorkIndexItem[];
}

export function EditorialWorkIndex({ title, projects }: EditorialWorkIndexProps) {
  return (
    <section className="tb-work-index">
      <h2>{title}</h2>
      <ul>
        {projects.map((project) => (
          <li key={`${project.title}-${project.href}`}>
            <a href={project.href}>
              <strong>{project.title}</strong>
              <span>{project.discipline}</span>
            </a>
          </li>
        ))}
      </ul>
    </section>
  );
}

.tb-work-index {
  --tb-wi-ink: #1e1e1c;
  --tb-wi-paper: #f0eee8;
  --tb-wi-accent: #e04e35;
  container-type: inline-size;
  padding: clamp(3rem, 6%, 7rem) clamp(1.25rem, 5%, 5.5rem);
  color: var(--tb-wi-ink);
  background: var(--tb-wi-paper);
}

.tb-work-index,
.tb-work-index * {
  box-sizing: border-box;
}

.tb-work-index h2 {
  max-width: 44rem;
  margin: 0 0 clamp(3rem, 7cqi, 7rem);
  font-size: clamp(2.6rem, 6vw, 5.8rem);
  font-size: clamp(2.6rem, 7cqi, 5.8rem);
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.025em;
  overflow-wrap: anywhere;
}

.tb-work-index ul {
  margin: 0;
  padding: 0;
  list-style: none;
  border-top: 0.2rem solid currentColor;
}

.tb-work-index li + li {
  border-top: 1px solid rgb(30 30 28 / 0.24);
}

.tb-work-index a {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(8rem, auto);
  gap: 1rem 2rem;
  align-items: center;
  min-height: 7rem;
  padding: 1rem 0;
  color: inherit;
  text-decoration: none;
  transition: color 150ms ease-out;
}

.tb-work-index a::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  background: var(--tb-wi-accent);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.tb-work-index a > * {
  position: relative;
  z-index: 1;
  transition: transform 180ms ease-out;
}

.tb-work-index a strong {
  min-width: 0;
  font-size: clamp(1.9rem, 5.5cqi, 4.8rem);
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.025em;
  overflow-wrap: anywhere;
}

.tb-work-index a span {
  font-size: 0.92rem;
  line-height: 1.4;
}

@media (hover: hover) and (pointer: fine) {
  .tb-work-index a:hover {
    color: #151715;
  }

  .tb-work-index a:hover::before {
    transform: scaleX(1);
  }

  .tb-work-index a:hover > * {
    transform: translateX(1.25rem);
  }
}

.tb-work-index a:focus-visible {
  outline: 3px solid var(--tb-wi-accent);
  outline-offset: 4px;
}

@container (max-width: 38rem) {
  .tb-work-index a {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 680px) {
  .tb-work-index a {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tb-work-index a,
  .tb-work-index a::before,
  .tb-work-index a > * {
    transition: none;
  }
}

@media (forced-colors: active) {
  .tb-work-index a::before {
    display: none;
  }
}
